{"query":"
            query {
              dashboardsGet (order: "GROUP_ID,GROUP_ORDER") {
                id: DASHBOARD_ID,
                url: DASHBOARD_URL,
                name: DASHBOARD_NAME,
                title: DASHBOARD_TITLE,
                isDarkMode: DARK_MODE,
                status: STATUS,
                owner: OWNER_USERID,
                access: ACCESS_GROUPS,
                noAccessMessage: NO_ACCESS_MESSAGE,
                icon: ICON,
                group:dim_dashboard_groups {
                  groupID:GROUP_ID,
                  groupName:GROUP_NAME
                },
                groupOrder: GROUP_ORDER,
                inputs {
                  defaultValue:DEFAULT_VALUE,
                  id:INPUT_ID,
                  input {
                    name:INPUT_NAME,
                    config:INPUT_CONFIG
                  }
                }
              }
            }       
          "}

{"query":"
            query {
              result:dimDashboardGroupsGet {
                groupID:GROUP_ID,
                groupName:GROUP_NAME
              }
            }       
          "}

{"query":"
            query {
              result:dimGqlQueriesGet(
                where: {
                  or: [{INACTIVE:{eq:0}}, {INACTIVE:{is:null}}]
                },
                order:"GROUP_ID"
              ) {
                id:GQL_ID,
                name:GQL_NAME,
                table:GQL_TABLE,
                group:dim_query_groups {
                  groupID:GROUP_ID,
                  groupName:GROUP_NAME
                },
                columns:query_columns(
                  where: {
                    IS_ACTIVE: 1
                  },
                  order:"COLUMN_ORDER"
                ) {
                  columnID:COLUMN_ID,
                  isActive:IS_ACTIVE,
                  column:COLUMN_NAME,
                  label:COLUMN_LABEL,
                  dashboardInput:COLUMN_DASHBOARD_INPUT,
                  formatType:COLUMN_FORMAT_TYPE,
                  multiplier:COLUMN_MULTIPLIER,
                  precision:COLUMN_PRECISION,
                  type:DATA_TYPE,
                  calculatedValue:CALCULATED_VALUE
                }
                where:GQL_WHERE,
                inactive:INACTIVE,
                dashboards:dashboards_queries {
                  dashboards {
                    dashboardID:DASHBOARD_ID,
                    name:DASHBOARD_NAME,
                    title:DASHBOARD_TITLE
                  }
                }
              }
            }       
          "}

{"query":"
            query {
              result:dimInputsGet(where: { INPUT_TYPE: 0 }) {
                id:INPUT_ID,
                name:INPUT_NAME,
                type:INPUT_TYPE,
                config:INPUT_CONFIG
              }
            }       
          "}

{"query":"
            query {
              result: dimStoreAlignmentGet(where: { and: { closed_ind:{eq:0}, temp_store_ind:{eq:0}  } }) {
                store_nbr
                market_nbr,
                region_nbr,
                region_name,
                subdiv_code,
                subdiv_name
              }
            }          
          "}
